@Composable fun Field(label:String,value:String,secret:Boolean=false,onChange:(String)->Unit){OutlinedTextField(value,onChange,label={Text(label)},modifier=Modifier.fillMaxWidth().padding(vertical=5.dp),singleLine=true,visualTransformation=if(secret)androidx.compose.ui.text.input.PasswordVisualTransformation() else androidx.compose.ui.text.input.VisualTransformation.None)}
@Composable fun DistrictPicker(value:String,onPick:(String)->Unit){var expanded by remember{mutableStateOf(false)};Box{OutlinedButton(onClick={expanded=true},Modifier.fillMaxWidth()){Text(value)};DropdownMenu(expanded,{expanded=false}){districts.forEach{DropdownMenuItem(text={Text(it)},onClick={onPick(it);expanded=false})}}}}
@Composable fun ErrorText(vm:EcoViewModel){val error by vm.error.collectAsState();error?.let{Text(it,color=MaterialTheme.colorScheme.error,modifier=Modifier.padding(12.dp))}}
@Composable fun AddListingScreen(vm:EcoViewModel){var title by remember{mutableStateOf("")};var cat by remember{mutableStateOf(categories[0])};var kg by remember{mutableStateOf("")};var area by remember{mutableStateOf(districts[0])};var desc by remember{mutableStateOf("")};var url by remember{mutableStateOf("")};Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(20.dp)){Text("Tambah material",fontSize=26.sp,fontWeight=FontWeight.Bold);Text("Bagikan material yang masih layak digunakan.",color=Color.Gray);Field("Judul material",title){title=it};var open by remember{mutableStateOf(false)};Box{OutlinedButton(onClick={open=true},Modifier.fillMaxWidth()){Text(cat)};DropdownMenu(open,{open=false}){categories.forEach{DropdownMenuItem(text={Text(it)},onClick={cat=it;open=false})}}};Field("Total berat (kg)",kg){kg=it};DistrictPicker(area){area=it};Field("Deskripsi",desc){desc=it};Field("URL foto (opsional)",url){url=it};Button(onClick={kg.toDoubleOrNull()?.takeIf{title.isNotBlank()&&it>0}?.let{vm.listing(ListingRequest(title,cat,it,area,desc,url));title=""}},Modifier.fillMaxWidth().padding(top=12.dp)){Text("Terbitkan listing")};ErrorText(vm)}}
@Composable fun ActivityScreen(vm:EcoViewModel){var tab by remember{mutableIntStateOf(0)};val incoming by vm.incoming.collectAsState();val outgoing by vm.outgoing.collectAsState();var qr by remember{mutableStateOf<Bitmap?>(null)};var completing by remember{mutableStateOf<Reservation?>(null)};var token by remember{mutableStateOf("")};var actual by remember{mutableStateOf("")};Column(Modifier.fillMaxSize().padding(18.dp)){Text("Aktivitas",fontSize=27.sp,fontWeight=FontWeight.Bold);TabRow(tab){listOf("Permintaan Masuk","Reservasi Saya").forEachIndexed{i,s->Tab(tab==i,{tab=i},text={Text(s)})}};LazyColumn(contentPadding=PaddingValues(vertical=12.dp)){items(if(tab==0)incoming else outgoing){r->Card(Modifier.fillMaxWidth().padding(bottom=10.dp)){Column(Modifier.padding(16.dp)){Text(r.listing?.title?:"Reservasi EcoLoop",fontSize=18.sp,fontWeight=FontWeight.Bold);Text("${r.requestedKg} kg · ${statusLabel(r.status)}",color=MaterialTheme.colorScheme.primary);if(tab==0&&r.status=="REQUESTED"){Row{TextButton(onClick={vm.approve(r.id,true)}){Text("Setujui")};TextButton(onClick={vm.approve(r.id,false)}){Text("Tolak")}}};if(tab==0&&r.status=="APPROVED")Button(onClick={completing=r}){Text("Selesaikan serah terima")};if(tab==1&&r.status=="APPROVED")Button(onClick={vm.handover(r.id){raw->qr=generateQr(raw)}}){Text("Tampilkan QR Serah Terima")}}}}};ErrorText(vm)}
 if(qr!=null)AlertDialog(onDismissRequest={qr=null},title={Text("QR Serah Terima")},text={Column(horizontalAlignment=Alignment.CenterHorizontally){androidx.compose.foundation.Image(qr!!.asImageBitmap(),null,Modifier.size(230.dp));Text("Tunjukkan kode ini kepada penyedia saat pengambilan.")}},confirmButton={TextButton(onClick={qr=null}){Text("Selesai")}})
 completing?.let{reservation->AlertDialog(onDismissRequest={completing=null},title={Text("Konfirmasi serah terima")},text={Column{Text("Masukkan token yang dipindai dari QR penerima dan berat aktual.");OutlinedTextField(token,{token=it},label={Text("Token QR")});OutlinedTextField(actual,{actual=it},label={Text("Berat aktual (kg)")})}},confirmButton={TextButton(onClick={actual.toDoubleOrNull()?.takeIf{token.isNotBlank()&&it>0}?.let{vm.complete(reservation.id,token,it);completing=null;token="";actual=""}}){Text("Selesaikan")}},dismissButton={TextButton(onClick={completing=null}){Text("Batal")}})}
}
private fun statusLabel(s:String)=when(s){"REQUESTED"->"Menunggu";"APPROVED"->"Disetujui";"REJECTED"->"Ditolak";"COMPLETED"->"Selesai";else->s}
private fun generateQr(value:String):Bitmap {val matrix=MultiFormatWriter().encode(value,BarcodeFormat.QR_CODE,640,640);return Bitmap.createBitmap(640,640,Bitmap.Config.ARGB_8888).also{for(x in 0 until 640)for(y in 0 until 640)it.setPixel(x,y,if(matrix[x,y])AndroidColor.BLACK else AndroidColor.WHITE)}}
@Composable fun ImpactScreen(vm:EcoViewModel){val impact by vm.impact.collectAsState();Column(Modifier.fillMaxSize().padding(22.dp)){Text("Dampak bersama",fontSize=27.sp,fontWeight=FontWeight.Bold);Text("Kontribusi untuk SDG 12.5",color=Color.Gray);Spacer(Modifier.height(20.dp));Card(Modifier.fillMaxWidth()){Column(Modifier.padding(22.dp)){Text("Material tersalurkan",color=Color.Gray);Text("%.2f kg".format(impact.totalKg),fontSize=34.sp,fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.primary)}};Card(Modifier.fillMaxWidth().padding(top=12.dp)){Column(Modifier.padding(22.dp)){Text("Transaksi berhasil",color=Color.Gray);Text("${impact.transferCount}",fontSize=34.sp,fontWeight=FontWeight.Bold)}};Text("Setiap penyaluran membantu menjaga material tetap berputar melalui penggunaan ulang dan daur ulang.",Modifier.padding(top=20.dp))}}
@Composable fun ProfileScreen(vm:EcoViewModel){val user by vm.user.collectAsState();Column(Modifier.fillMaxSize().padding(22.dp)){Text("Profil",fontSize=28.sp,fontWeight=FontWeight.Bold);Spacer(Modifier.height(20.dp));Text(user?.name?:"Pengguna EcoLoop",fontSize=22.sp,fontWeight=FontWeight.SemiBold);Text(user?.email?:"",color=Color.Gray);Text(user?.contact?:"Kontak belum ditambahkan",Modifier.padding(top=12.dp));Text("${user?.district.orEmpty()}, ${user?.city?:"Jakarta"}");Button(onClick={vm.logout()},Modifier.fillMaxWidth().padding(top=32.dp)){Text("Keluar")}}}
